package com.vms.vendorcontractmanagement.service; import com.vms.vendorcontractmanagement.dto.ContractDtos.*; import com.vms.vendorcontractmanagement.entity.*; import com.vms.vendorcontractmanagement.exception.*; import com.vms.vendorcontractmanagement.repository.*; import lombok.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class ContractService {final ContractRepository contracts;final VendorRepository vendors;final AuditService audit; @Transactional(readOnly=true) public Page<Response> list(String s,String status,Pageable p){return contracts.search(blank(s),blank(status),p).map(this::dto);} public Response get(Long id){return dto(find(id));} public List<Response> expiring(int days){return contracts.expiring(LocalDate.now(),LocalDate.now().plusDays(days)).stream().map(this::dto).toList();} @Transactional public Response create(Request r){if(contracts.existsByContractNumber(r.contractNumber()))throw new ApiException(HttpStatus.CONFLICT,"Contract number already exists");Contract c=apply(new Contract(),r);contracts.save(c);audit.log("CREATE","CONTRACT",c.getId(),null,c.getContractNumber());return dto(c);} @Transactional public Response update(Long id,Request r){Contract c=find(id);String old=c.getContractNumber();apply(c,r);audit.log("UPDATE","CONTRACT",id,old,c.getContractNumber());return dto(c);} @Transactional public void delete(Long id){Contract c=find(id);contracts.delete(c);audit.log("DELETE","CONTRACT",id,c.getContractNumber(),null);} Contract find(Long id){return contracts.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Contract not found"));} Contract apply(Contract c,Request r){if(!r.endDate().isAfter(r.startDate()))throw new ApiException(HttpStatus.BAD_REQUEST,"End date must be after start date");c.setContractNumber(r.contractNumber());c.setVendor(vendors.findById(r.vendorId()).orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"Vendor not found")));c.setStartDate(r.startDate());c.setEndDate(r.endDate());c.setContractValue(r.contractValue());c.setPaymentFrequency(r.paymentFrequency());c.setStatus(r.status()==null?status(r.endDate()):r.status());c.setRenewalStatus(r.renewalStatus()==null?"PENDING":r.renewalStatus());return c;} String status(LocalDate d){return d.isBefore(LocalDate.now())?"EXPIRED":"ACTIVE";} Response dto(Contract c){long d=java.time.temporal.ChronoUnit.DAYS.between(LocalDate.now(),c.getEndDate());return new Response(c.getId(),c.getContractNumber(),c.getVendor().getId(),c.getVendor().getVendorName(),c.getStartDate(),c.getEndDate(),c.getContractValue(),c.getPaymentFrequency(),status(c.getEndDate()),c.getRenewalStatus(),d,d<30?"HIGH":d<=90?"MEDIUM":"LOW");} String blank(String s){return s==null||s.isBlank()?null:s;} }
